<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import BiExecutionMessage from './BiExecutionMessage.vue';
import {AlertCircle,CheckCircle2,LoaderCircle,RefreshCw} from 'lucide-vue-next';
import {flowResults,loadDate,loadLabel,observingLoadStates} from '../lib/bi-loads';
import {scheduleContextLabel} from '../lib/schedule-editor';
import {createRequestGuard} from '../lib/async-response';
type Item=Record<string,any>;
const props=defineProps<{execution?:Item;executionId?:string;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const current=ref<Item|null>(props.execution??null);const busy=ref(false);const error=ref('');const guard=createRequestGuard();let timer:ReturnType<typeof setInterval>|undefined;let polling=false;
const id=computed(()=>props.executionId??props.execution?.id);const rows=computed(()=>flowResults(current.value?.bindings??[],current.value?.proof??null));
const hasCounters=computed(()=>rows.value.some(flow=>typeof flow.rows_in==='number'||typeof flow.rows_out==='number'));
const watching=computed(()=>observingLoadStates.includes(current.value?.status??''));
async function load(observe=false){if(!id.value||polling)return;const valid=guard.next();polling=true;if(observe)busy.value=true;try{const result=await props.request(`/bi-loads/${id.value}${observe?'/observe':''}`,observe?'POST':'GET');if(valid()){current.value=result;error.value='';}}catch(e){if(valid())error.value=(e as Error).message;}finally{if(valid()){polling=false;busy.value=false;}}}
watch(()=>props.execution,value=>{if(value)current.value=value;});
watch(id,()=>{guard.invalidate();polling=false;current.value=props.execution??null;void load();});
onMounted(()=>{if(!current.value)void load();timer=setInterval(()=>{if(!document.hidden&&watching.value)void load();},5000);});
onUnmounted(()=>{guard.invalidate();if(timer)clearInterval(timer);});
</script>
<template><section class="bi-load-status" :class="{success:current?.status==='succeeded',attention:current&&!watching&&current.status!=='succeeded'}" aria-label="Resultado da atualização" aria-live="polite">
 <header><LoaderCircle v-if="watching" :size="18" class="spin"/><CheckCircle2 v-else-if="current?.status==='succeeded'" :size="18"/><AlertCircle v-else :size="18"/><div><strong>{{current?loadLabel(current.status):'Consultando acompanhamento…'}}</strong><small v-if="current?.requested_at">Solicitado em {{loadDate(current.requested_at)}} · Brasília</small></div><button class="secondary-button" :disabled="busy" @click="load(true)"><RefreshCw :size="14" :class="{spin:busy}"/>Conferir agora</button></header>
 <p v-if="current?.message">{{current.message}}</p><p v-if="current?.status==='accepted'||current?.status==='requesting'">O envio ainda não comprova a conclusão. O resultado será conferido sem reenviar a carga.</p><p v-if="['access_changed','needs_revalidation'].includes(current?.status??'')">O BI pode continuar executando a carga. Este aviso pausa apenas a consulta do resultado. Use Conferir agora para validar seu acesso atual e consultar o histórico.</p>
 <ol v-if="rows.length"><li v-for="(flow,index) in rows" :key="index"><span><strong>{{flow.name}}</strong><small>{{flow.context===null?'Forma de carga não informada no histórico':scheduleContextLabel(flow.context)}}</small></span><span>{{({pending:'Aguardando',running:'Em execução',succeeded:'Concluída',failed:'Falhou',unknown:'Não confirmado'} as Record<string,string>)[flow.status]??'Não confirmado'}}<small v-if="typeof flow.rows_in==='number'">{{flow.rows_in.toLocaleString('pt-BR')}} linhas de entrada</small><small v-if="typeof flow.rows_out==='number'">{{flow.rows_out.toLocaleString('pt-BR')}} linhas de saída</small></span><BiExecutionMessage v-if="flow.message" :message="flow.message" :state="flow.status"/></li></ol>
 <p v-if="hasCounters" class="load-counter-note">Contadores do processamento informados pelo BI; não comprovam a quantidade de registros na tabela. Uma mesma linha pode passar por várias etapas. Confira os dados e os indicadores da tabela.</p>
 <small v-if="current?.finished_at">Término informado pelo BI: {{loadDate(current.finished_at)}} · Brasília</small><details v-if="current?.run_id||current?.correlation"><summary>Como o resultado foi conferido</summary><p>{{current?.correlation==='response_id'?'Identificador informado na resposta do envio.':current?.correlation==='unique_after_request'?'Vínculo inferido: uma única execução nova compatível foi encontrada nos cinco minutos seguintes ao pedido. O BI não informou um identificador no envio.':'O vínculo entre este pedido e uma execução do BI ainda não foi confirmado.'}}</p><p v-if="current?.proof?.evidence==='schedule_history'">Resultado final do histórico. Essa consulta não informa contagens de linhas nem horários por fonte.</p><code v-if="current?.run_id">{{current.run_id}}</code></details><p v-if="error" class="form-error" role="alert">{{error}}</p>
</section></template>
<style scoped>
.bi-load-status{padding:17px;border:1px solid #dce6f4;border-radius:10px;background:#f8fbff;margin:15px 0;color:#536e91}.bi-load-status header{display:flex;gap:10px;align-items:flex-start}.bi-load-status header>div{flex:1;min-width:0}.bi-load-status strong{font-size:12px;overflow-wrap:anywhere}.bi-load-status small{display:block;color:#879ab3;font-size:10px;line-height:1.8;margin-top:4px}.bi-load-status p{font-size:12px;line-height:1.8;margin:12px 0}.bi-load-status ol{list-style:none;padding:0;margin:14px 0}.bi-load-status li{display:flex;flex-wrap:wrap;gap:10px;justify-content:space-between;padding:12px 0;border-top:1px solid #e1e9f4;font-size:11px}.bi-load-status li>p{width:100%;margin:0}.bi-load-status li>span:last-of-type{text-align:right}.bi-load-status .load-counter-note{font-size:11px;color:#687f9d}.bi-load-status details{margin-top:12px;font-size:10px}.bi-load-status summary{cursor:pointer}.bi-load-status code{font-size:10px;overflow-wrap:anywhere}.bi-load-status.success{border-color:#c8e2d4;background:#f6fcf8}.bi-load-status.attention{border-color:#ebdcc2;background:#fffbf4}.bi-load-status .secondary-button{font-size:10px;padding:7px;min-height:30px}@media(max-width:600px){.bi-load-status header{display:grid;grid-template-columns:18px minmax(0,1fr)}.bi-load-status header>button{grid-column:2;margin-left:0;justify-self:start}.bi-load-status li{gap:7px}}
</style>
